window.__WB_TEXTBOOK__ = [{"id": "ostep", "name": "OSTEP · Operating Systems: Three Easy Pieces", "author": "Remzi H. Arpaci-Dusseau & Andrea C. Arpaci-Dusseau", "level": "系统底层核心", "chapters": [{"cid": "OSTEP-01", "title": "进程抽象与受限直接执行 (LDE)", "summary": "操作系统通过虚拟化 CPU 将单一物理处理器复用为多个并发运行的逻辑进程。核心机制是受限直接执行（Limited Direct Execution, LDE）：程序在用户态（User Mode）直接运行于硬件之上以保证近乎原生的执行效率，但一旦执行特权指令（如磁盘 I/O、修改页表或分配内存），硬件立即触发陷阱（Trap）切换至内核态（Kernel Mode），由内核通过陷阱表（Trap Table）接管控制权。为了防止恶意或死循环进程独占 CPU，内核在启动时配置时钟中断（Timer Interrupt），每隔数毫秒强制剥夺当前进程控制权，并通过上下文切换（Context Switch）保存旧进程的寄存器与内核栈指针，恢复新进程状态，从而实现透明的时分复用。", "template_cpp": "#include <stdio.h>\n#include <stdlib.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\nint main() {\n    int fd[2];\n    if (pipe(fd) < 0) return 1;\n    pid_t rc = fork();\n    if (rc < 0) {\n        fprintf(stderr, \"fork failed\\n\");\n        exit(1);\n    } else if (rc == 0) {\n        close(fd[0]);\n        const char *msg = \"hello from child\";\n        write(fd[1], msg, 16);\n        close(fd[1]);\n        _exit(0);\n    } else {\n        close(fd[1]);\n        char buf[32] = {0};\n        read(fd[0], buf, sizeof(buf) - 1);\n        close(fd[0]);\n        waitpid(rc, NULL, 0);\n        printf(\"Parent received: %s\\n\", buf);\n    }\n    return 0;\n}", "pitfalls": "调用 `fork()` 后父子进程执行顺序不确定，不可假设子进程先于父进程运行；在多线程进程中调用 `fork()` 仅复制当前线程，极易因其他线程持有锁而导致死锁；子进程退出应优先使用 `_exit()` 避免重复刷新父进程 `stdio` 缓冲区。", "workbench_tags": ["进程管理", "系统调用", "上下文切换", "LDE"], "problems": [{"oj": "教材精选题", "pid": "OSTEP-Ch05-01", "title": "fork() 与写时复制 (COW) 地址空间隔离分析", "diff": "基础", "hint": "1. **破题思路**：理解 `fork()` 创建独立虚拟地址空间但延迟物理页拷贝的机制。\n2. **解答要点**：父进程定义局部变量 `x = 100` 后调用 `fork()`。初期父子进程页表指向同一物理页且标记为只读；当子进程执行 `x = 200` 时触发缺页/保护异常（Page Fault），内核分配新物理页并复制原页内容，将子进程页表项更新为可写。因此父进程读取 `x` 仍为 $100$，子进程为 $200$，实现逻辑隔离且将 `fork()` 开销从 $O(N)$ 降至仅拷贝页表的开销。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch06-02", "title": "受限直接执行中的系统调用与硬件栈切换", "diff": "中档", "hint": "1. **破题思路**：追踪用户态执行 `read()` 系统调用时硬件与内核协作的精确步骤。\n2. **解答要点**：(1) 用户程序将系统调用号放入指定寄存器（如 x86-64 的 `%rax`），执行 `syscall` / `int 0x80` 陷阱指令；(2) 硬件自动将用户态 PC、标志位及栈指针（RSP）压入内核预配置的内核栈（通过 TSS/MSR 定位），并将特权级从 Ring 3 切至 Ring 0；(3) 硬件查陷阱表跳转至内核处理程序；(4) 内核校验参数并完成 I/O 后执行 `sysret`/`iret` 恢复用户栈与 PC，降级回 Ring 3。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch06-03", "title": "协作式与抢占式上下文切换开销定量测量", "diff": "中档", "hint": "1. **破题思路**：利用双管道（Pipe）实现两进程乒乓通信，通过高精度计时器测量单次上下文切换耗时。\n2. **解答要点**：父进程向管道 A 写 $1$ 字节并阻塞读管道 B；子进程阻塞读管道 A 后向管道 B 写 $1$ 字节。每轮循环触发 $2$ 次上下文切换（父 $\\to$ 子 $\\to$ 父）。使用 `sched_setaffinity` 将两进程绑定至同一 CPU 核心，循环 $N = 10^5$ 次记录总时间 $T$，则单次上下文切换（含系统调用）平均耗时约为 $\\frac{T}{2N}$。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch05-04", "title": "连续多次 fork() 的进程树规模与输出行数推导", "diff": "压轴", "hint": "1. **破题思路**：画出二叉树状进程派生模型，并区分行缓冲（终端）与全缓冲（重定向到文件）对 `printf` 的影响。\n2. **解答要点**：若代码连续执行 $n$ 次无条件 `fork()`，总进程数为 $2^n$。若每次 `fork()` 后打印无换行符的字符串 `printf(\"A\")`，在重定向至文件（全缓冲）时，缓冲区内容会被 `fork()` 连带复制给子进程，导致每个进程在退出刷新缓冲区时输出多个 `A`。对 `for (int i=0; i<n; ++i) { fork(); printf(\"A\"); }`，最终在全缓冲下总输出字符数为 $\\sum_{k=1}^{n} 2^k = 2^{n+1}-2$ 个（每层新进程继承父进程缓冲的规律需按每步位置逐层递推，当 `printf` 在 `fork` 后时，第 $i$ 轮有 $2^i$ 个进程各向自身缓冲写入 $1$ 个字符，最终全部 $2^n$ 个进程共保留并刷新 $n \\cdot 2^{n-1}$ 个字符）。"}]}, {"cid": "OSTEP-02", "title": "CPU 调度与多级反馈队列 (MLFQ)", "summary": "CPU 调度需要在周转时间（Turnaround Time，$T_{\\text{completion}} - T_{\\text{arrival}}$）与响应时间（Response Time，$T_{\\text{firstrun}} - T_{\\text{arrival}}$）之间取得平衡。最短作业优先（SJF）与最短完成时间优先（STCF）在理论上能最小化平均周转时间，但依赖不可预知的作业运行时间；轮转调度（Round-Robin）通过固定时间片显著降低响应时间，却以牺牲周转时间为代价。OSTEP 提出的多级反馈队列（MLFQ）通过历史行为预测未来：设置多级优先级队列，新作业置顶；高优先级队列优先且采用短时间片，用完时间片则降级（识别 CPU 密集型），主动让出 CPU（如等待 I/O）则保持优先级（保护交互型）；并引入周期性优先级提升（Priority Boost）防止饥饿，配合精确计时防作弊。", "template_cpp": "#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nstruct Job {\n    int id, arrival, burst, remaining, first_run = -1, finish = 0;\n};// STCF (Preemptive SJF) Simulator\n\nint main() {\n    vector<Job> jobs = {{1, 0, 8, 8}, {2, 1, 4, 4}, {3, 2, 2, 2}};\n    int t = 0, done = 0, n = jobs.size();\n    while (done < n) {\n        int best = -1;\n        for (int i = 0; i < n; ++i) {\n            if (jobs[i].arrival <= t && jobs[i].remaining > 0) {\n                if (best == -1 || jobs[i].remaining < jobs[best].remaining) best = i;\n            }\n        }\n        if (best == -1) { ++t; continue; }\n        if (jobs[best].first_run == -1) jobs[best].first_run = t;\n        jobs[best].remaining--;\n        ++t;\n        if (jobs[best].remaining == 0) { jobs[best].finish = t; ++done; }\n    }\n    for (auto &j : jobs)\n        cout << \"Job \" << j.id << \" Turnaround=\" << (j.finish - j.arrival)\n             << \" Response=\" << (j.first_run - j.arrival) << \"\\n\";\n    return 0;\n}", "pitfalls": "护航效应（Convoy Effect）：FIFO 调度下长作业阻塞后续短作业导致平均周转时间飙升；MLFQ 若缺少 Priority Boost 会使底层 CPU 密集型作业永久饥饿；时间片过小导致上下文切换开销占比过高，吞吐量骤降。", "workbench_tags": ["CPU调度", "MLFQ", "CFS", "周转时间"], "problems": [{"oj": "教材精选题", "pid": "OSTEP-Ch07-01", "title": "FIFO、SJF 与 STCF 平均周转时间对比计算", "diff": "基础", "hint": "1. **破题思路**：按时间轴模拟三类调度器对非同时到达作业的抢占行为。\n2. **解答要点**：设作业 $A(0, 100)$，$B(10, 10)$，$C(10, 10)$（括号内为到达时间与运行时间）。\n- FIFO：$A$ 于 $100$ 完成，$B$ 于 $110$，$C$ 于 $120$，平均周转时间 $= \\frac{100 + (110-10) + (120-10)}{3} = 103.33$。\n- SJF（非抢占）：$A$ 已在运行不被抢占，结果同 FIFO 为 $103.33$。\n- STCF（抢占）：$t=10$ 时 $A$ 剩 $90 > 10$，故抢占执行 $B(10\\to 20)$、$C(20\\to 30)$，最后 $A(30\\to 120)$。平均周转时间 $= \\frac{120 + 10 + 20}{3} = 50.0$。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch08-02", "title": "MLFQ 防作弊与优先级提升机制设计", "diff": "中档", "hint": "1. **破题思路**：识别恶意进程在时间片结束前主动发起伪 I/O 以骗取高优先级的漏洞。\n2. **解答要点**：旧规则中“每次在时间片用完前主动让出 CPU 即保持优先级”易被利用（如占用 $99\\%$ 时间片后发起空 `read`）。修复方案为**累计计时（Rule 4 重写）**：调度器记录进程在当前层级消耗的**总 CPU 时间**，无论其是否主动让出，只要累计耗时达到该层时间片配额 $Q_i$，即强制降级至第 $i-1$ 层；同时每隔周期 $S$ 将所有进程重置回最高层，彻底消除饥饿并避免因行为模式变化（CPU 型转为交互型）导致的永久低优先级。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch09-03", "title": "彩票调度与步长调度 (Stride Scheduling) 比例公平性", "diff": "中档", "hint": "1. **破题思路**：对比随机概率调度与确定性步长调度的收敛误差。\n2. **解答要点**：设进程 $A, B, C$ 彩票数为 $100, 50, 250$，取大常数 $M = 10000$，则各自步长 $\\text{stride}_i = \\frac{M}{\\text{tickets}_i}$，分别为 $100, 200, 40$。每次选择当前 `pass` 值最小的进程运行并累加其 `stride`。当 $C$ 运行 $5$ 次（`pass` 达 $200$）、$A$ 运行 $2$ 次（`pass` 达 $200$）、$B$ 运行 $1$ 次（`pass` 达 $200$）时，恰好完成一个精确周期 $8$ 次调度，CPU 占比严格等于 $2:1:5$，消除了彩票调度在短时间窗口内的随机抖动。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch10-04", "title": "Linux CFS 虚拟运行时间 (vruntime) 与权重计算", "diff": "压轴", "hint": "1. **破题思路**：利用 CFS 加权虚拟时间推进公式 $\\Delta vruntime = \\Delta t \\cdot \\frac{\\text{weight}_0}{\\text{weight}_i}$ 求解调度周期。\n2. **解答要点**：基准权重 $\\text{weight}_0 = 1024$（nice=0）。若两进程 nice 值分别为 $0$（权重 $1024$）与 $5$（权重 $335$），调度周期 `sched_latency` $= 48\\text{ ms}$。两进程分配的实际物理时间片按权重比例切分：$t_0 = 48 \\times \\frac{1024}{1024+335} \\approx 36.17\\text{ ms}$，$t_1 = 48 \\times \\frac{335}{1359} \\approx 11.83\\text{ ms}$。在一个周期结束时，二者积累的 `vruntime` 增量严格相等：$\\Delta v_0 = 36.17 \\times 1 = 36.17$，$\\Delta v_1 = 11.83 \\times \\frac{1024}{335} \\approx 36.17$，红黑树始终保持公平平衡。"}]}, {"cid": "OSTEP-03", "title": "虚拟内存、分页、TLB 与页面置换", "summary": "虚拟内存通过硬件 MMU 与操作系统协同，为每个进程提供私有的连续地址空间假象。现代系统普遍采用多级页表（Multi-level Page Table）按需分配页表页以压缩内存占用，例如 x86-64 采用四级页表（PGD/PUD/PMD/PTE）管理 $48$ 位虚拟地址。为消除每次访存带来的多级页表查询延迟，CPU 内置转译后备缓冲器（TLB）缓存热门 VPN 到 PFN 的映射，利用时间与空间局部性实现极高命中率。当物理内存耗尽时，OS 借助页面置换算法（如近似 LRU 的时钟算法 Clock Algorithm）结合页表项中的访问位（Reference Bit）与脏位（Dirty Bit），优先淘汰近期未访问且未修改的页面，避免工作集过大引发系统颠簸（Thrashing）。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Frame { int page = -1; bool ref = false; bool dirty = false; };\n\nint clock_replace(vector<Frame>& frames, int& hand, int new_page, bool is_write) {\n    for (auto &f : frames) {\n        if (f.page == new_page) { f.ref = true; if (is_write) f.dirty = true; return 0; } // Hit\n    }\n    while (true) {\n        if (!frames[hand].ref) {\n            frames[hand] = {new_page, true, is_write};\n            hand = (hand + 1) % frames.size();\n            return 1; // Page Fault\n        }\n        frames[hand].ref = false;\n        hand = (hand + 1) % frames.size();\n    }\n}\n\nint main() {\n    vector<Frame> frames(3);\n    int hand = 0, faults = 0;\n    vector<int> seq = {1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5};\n    for (int p : seq) faults += clock_replace(frames, hand, p, false);\n    cout << \"Clock Page Faults: \" << faults << \"\\n\";\n    return 0;\n}", "pitfalls": "上下文切换时未刷新 TLB 或未启用 ASID/PCID 会导致跨进程地址映射错误；Belady 异常（FIFO 算法下增加物理帧数反而导致缺页次数上升）；忽略大页（Huge Page）对减少 TLB Miss 的显著收益。", "workbench_tags": ["虚拟内存", "多级页表", "TLB", "页面置换"], "problems": [{"oj": "教材精选题", "pid": "OSTEP-Ch18-01", "title": "二级页表大小计算与虚拟地址切分", "diff": "基础", "hint": "1. **破题思路**：根据虚拟地址位数、页大小及 PTE 大小反推每级页表索引位数与页表页数。\n2. **解答要点**：设 $32$ 位虚拟地址，页大小 $4\\text{ KB} = 2^{12}\\text{ B}$，PTE 占 $4\\text{ B}$。则页内偏移（Offset）占 $12$ 位，VPN 占 $20$ 位。一页可存放 $\\frac{4096}{4} = 1024 = 2^{10}$ 个 PTE，故二级页表索引恰好划分为：10 位页目录索引（PDI）+ 10 位页表索引（PTI）+ 12 位偏移。页目录固定占 $1$ 页（$4\\text{ KB}$），若进程仅使用 $4\\text{ MB}$ 连续内存（$1024$ 页），仅需 $1$ 个页目录页 + $1$ 个二级页表页 $= 8\\text{ KB}$，远小于线性页表的 $4\\text{ MB}$。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch19-02", "title": "TLB 命中率与有效访存时间 (EMAT) 计算", "diff": "中档", "hint": "1. **破题思路**：区分 TLB 命中、TLB 缺失但内存命中、以及四级页表下的逐级访存次数。\n2. **解答要点**：设 TLB 访问耗时 $1\\text{ ns}$，物理内存访问耗时 $100\\text{ ns}$，TLB 命中率 $98\\%$，采用四级页表且无缺页。TLB 命中耗时 $1 + 100 = 101\\text{ ns}$；TLB 缺失需查 $4$ 级页表再取数据，共 $5$ 次内存访问，耗时 $1 + 5 \\times 100 = 501\\text{ ns}$。因此 $\\text{EMAT} = 0.98 \\times 101 + 0.02 \\times 501 = 109\\text{ ns}$。可见若命中率降至 $90\\%$，EMAT 将恶化至 $141\\text{ ns}$。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch22-03", "title": "FIFO、LRU 与 OPT 页面置换缺页次数对比及 Belady 异常", "diff": "中档", "hint": "1. **破题思路**：对经典引用串手工模拟队列/栈状态，验证栈型算法（LRU/OPT）无 Belady 异常。\n2. **解答要点**：引用串 `1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5`。在 $3$ 帧下，FIFO 缺页 $9$ 次；在 $4$ 帧下，FIFO 缺页反而增至 $10$ 次（发生 Belady 异常）。而 LRU 与 OPT 满足**包含性质**（$k$ 帧集合始终是 $k+1$ 帧集合的子集），因此帧数增加时缺页次数严格单调不增。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch23-04", "title": "写时复制 fork() 与缺页异常处理完整路径", "diff": "压轴", "hint": "1. **破题思路**：结合硬件权限位与内核 `vm_area_struct`（VMA）判定合法写操作与真实段错误。\n2. **解答要点**：当进程写入只读页触发 Page Fault（硬件将出错虚拟地址存入 CR2，压入错误码）时，内核处理程序首先查询进程 VMA 链表：(1) 若地址不在任何 VMA 内，发送 `SIGSEGV`；(2) 若在 VMA 内且 VMA 标记为可写（`VM_WRITE`），但页表项（PTE）为只读且引用计数 $> 1$，则判定为 COW 写保护异常：内核分配新物理页，拷贝原页数据，修改当前进程 PTE 指向新页并置可写位，递减原物理页引用计数并刷新当前核 TLB，最后返回用户态重新执行触发异常的写指令。"}]}, {"cid": "OSTEP-04", "title": "并发原语：锁、条件变量与信号量", "summary": "多线程共享进程地址空间带来竞态条件（Race Condition），其根源在于“读取-修改-写入”临界区指令序列的非原子性。硬件提供原子指令（如 Test-And-Set、Compare-And-Swap、LL/SC）作为构建自旋锁（Spinlock）的基石，但纯自旋在单核或高争用场景下会严重浪费 CPU 周期，且受缓存一致性总线流量拖累。为此操作系统结合硬件原子指令与内核队列（如 Linux Futex），在无争用时用户态快速加锁，争用时主动休眠让出 CPU。对于线程间复杂状态同步（如生产者-消费者模型），需使用互斥锁配合条件变量（Condition Variable），并严格遵循 `while` 循环检查条件与 Mesa 语义，或使用信号量（Semaphore）统一管理计数资源。", "template_cpp": "#include <iostream>\n#include <thread>\n#include <mutex>\n#include <condition_variable>\n#include <queue>\nusing namespace std;\n\ntemplate <typename T>\nclass BoundedQueue {\n    queue<T> q_;\n    size_t cap_;\n    mutex mtx_;\n    condition_variable not_full_, not_empty_;\npublic:\n    explicit BoundedQueue(size_t cap) : cap_(cap) {}\n    void push(T val) {\n        unique_lock<mutex> lk(mtx_);\n        not_full_.wait(lk, [&] { return q_.size() < cap_; });\n        q_.push(move(val));\n        not_empty_.notify_one();\n    }\n    T pop() {\n        unique_lock<mutex> lk(mtx_);\n        not_empty_.wait(lk, [&] { return !q_.empty(); });\n        T val = move(q_.front());\n        q_.pop();\n        not_full_.notify_one();\n        return val;\n    }\n};", "pitfalls": "在条件变量等待中使用 `if` 而非 `while` 导致虚假唤醒（Spurious Wakeup）或被其他消费者抢先消费后越界；混合使用单一条件变量同时唤醒生产者和消费者引发互锁/死锁；锁顺序不一致引发 AB-BA 死锁。", "workbench_tags": ["并发控制", "互斥锁", "条件变量", "信号量"], "problems": [{"oj": "教材精选题", "pid": "OSTEP-Ch30-01", "title": "生产者-消费者模型中单一条件变量的死锁构造", "diff": "基础", "hint": "1. **破题思路**：追踪多消费者场景下 `signal` 唤醒同阵营线程导致全员阻塞的路径。\n2. **解答要点**：假设缓冲区容量为 $1$，初始为空。消费者 $C_1, C_2$ 先后调用 `wait(&cond, &mtx)` 休眠。随后生产者 $P$ 放入 $1$ 个元素并调用 `signal(&cond)` 唤醒 $C_1$，自身继续生产发现已满也进入 `cond` 等待。$C_1$ 消费完元素后调用 `signal(&cond)`，若恰好唤醒的是 $C_2$ 而非 $P$，则 $C_2$ 醒来发现队列仍空再次休眠，此时 $P, C_1, C_2$ 全部处于阻塞态，系统永久死锁。解决方法：使用两个独立条件变量 `empty` 与 `fill` 定向唤醒。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch31-02", "title": "用信号量实现公平无饥饿的读者-写者锁", "diff": "中档", "hint": "1. **破题思路**：在传统读者优先锁中引入“闸门信号量”（Turnstile），防止写者被连续到达的读者饿死。\n2. **解答要点**：维护 `lock`（保护 `readers` 计数）、`writelock`（控制写互斥）与 `turnstile`（初值均为 $1$）。读者进入前先 `sem_wait(&turnstile)` 再 `sem_post(&turnstile)`，随后抢占 `lock` 并在首个读者时等待 `writelock`。写者进入时先 `sem_wait(&turnstile)` 阻塞后续新读者，再等待 `writelock` 排空当前已进入的读者，写完后同时释放 `writelock` 与 `turnstile`，保证写者不会无限饥饿。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch28-03", "title": "Ticket Lock 实现与多核缓存行乒乓 (Cache Ping-Pong) 优化", "diff": "中档", "hint": "1. **破题思路**：利用硬件 `fetch_and_add` 保证 FIFO 公平性，并解释为何 MCS 锁能进一步消除总线风暴。\n2. **解答要点**：Ticket Lock 维护 `ticket` 与 `turn` 两个变量。线程加锁时执行 `my_turn = fetch_and_add(&ticket, 1)`，然后自旋等待 `turn == my_turn`。解锁时仅执行 `turn++`。该设计消除了 Test-And-Set 的饥饿问题，但所有等待核仍轮询同一共享变量 `turn`，解锁修改 `turn` 会使所有核的 L1 Cache Line 失效。MCS 锁通过让每个线程在各自本地节点自旋，将总线流量从 $O(N)$ 降至 $O(1)$。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch31-04", "title": "哲学家就餐问题：破除循环等待与信号量防死锁", "diff": "压轴", "hint": "1. **破题思路**：从死锁四条件（互斥、占有且等待、不可抢占、循环等待）中破坏“循环等待”。\n2. **解答要点**：$5$ 位哲学家围坐，若全部先拿左手筷子再拿右手筷子则形成环路死锁。标准 OSTEP 解法：让 $0\\sim 3$ 号哲学家先拿左筷子（编号较小者）再拿右筷子，而让 $4$ 号哲学家反序先拿右筷子（编号 $0$）再拿左筷子（编号 $4$）。所有加锁请求均严格遵循全局偏序 $0 < 1 < 2 < 3 < 4$，从数学上彻底消除资源分配图中的有向环，无需全局大锁即可实现高并发。"}]}, {"cid": "OSTEP-05", "title": "持久性存储：文件系统与日志崩溃一致性", "summary": "文件系统的核心任务是将持久化的扁平扇区数组抽象为目录树与文件。经典 Unix 文件系统（VSFS）将磁盘划分为超级块、inode 位图、数据位图、inode 表与数据区，利用直接指针与多级间接指针平衡小文件访问速度与大文件容量上限。由于断电或系统崩溃可能发生在多步元数据写入之间，文件系统面临崩溃一致性（Crash Consistency）挑战：例如新建文件需写入数据块、inode 与位图，任意部分缺失都将导致孤儿块或垃圾数据。预写日志（Write-Ahead Logging / Journaling）通过先将事务写入日志区并落盘提交（Journal Commit），再异步归位到最终位置（Checkpoint），确保文件系统在崩溃重启后通过日志重放快速恢复到一致状态。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <cstdint>\nusing namespace std;\n\nstruct Inode {\n    uint32_t size = 0;\n    int direct[12] = {-1};\n    int single_indirect = -1;\n};\n\nint map_block(const Inode& node, int lbn, const vector<int>& indirect_table) {\n    if (lbn < 12) return node.direct[lbn];\n    int idx = lbn - 12;\n    if (node.single_indirect != -1 && idx < (int)indirect_table.size())\n        return indirect_table[idx];\n    return -1;\n}\n\nint main() {\n    Inode f; f.direct[0] = 105; f.single_indirect = 200;\n    vector<int> ind(1024, -1); ind[0] = 310;\n    cout << \"LBN 0 -> PBN \" << map_block(f, 0, ind) << \"\\n\";\n    cout << \"LBN 12 -> PBN \" << map_block(f, 12, ind) << \"\\n\";\n    return 0;\n}", "pitfalls": "忽略写入重排（Disk Write Reordering）：磁盘控制器缓存可能先于日志提交块将数据写入最终位置，必须显式下发 `fsync`/Cache Flush 屏障；数据日志（Data Journaling）写入放大一倍，生产环境多默认采用仅记录元数据的 Ordered Mode。", "workbench_tags": ["文件系统", "Inode", "Journaling", "崩溃一致性"], "problems": [{"oj": "教材精选题", "pid": "OSTEP-Ch40-01", "title": "多级索引 Inode 最大文件容量计算", "diff": "基础", "hint": "1. **破题思路**：统计直接指针及各级间接指针所能索引的总数据块数，乘以单块字节数。\n2. **解答要点**：设块大小 $4\\text{ KB}$，块号指针占 $4\\text{ B}$，则每块可存 $\\frac{4096}{4} = 1024 = 2^{10}$ 个指针。若 inode 含 $12$ 个直接指针、$1$ 个一级间接、$1$ 个二级间接、$1$ 个三级间接指针：\n总块数 $= 12 + 2^{10} + (2^{10})^2 + (2^{10})^3 = 12 + 1024 + 2^{20} + 2^{30}$。\n最大文件容量 $\\approx 2^{30} \\times 4\\text{ KB} = 4\\text{ TB}$（精确值为 $4\\text{ TB} + 4\\text{ GB} + 4.05\\text{ MB}$）。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch40-02", "title": "路径解析与文件追加写入的磁盘 I/O 次数追踪", "diff": "中档", "hint": "1. **破题思路**：在无缓存冷启动条件下，逐一清点读取目录、inode 与写回元数据的 I/O 操作。\n2. **解答要点**：打开并向 `/foo/bar` 追加 $1$ 个新数据块（假设 `/foo` 与 `bar` 均不超过 $1$ 块）：\n- 读：根目录 inode $\\to$ 根目录数据块 $\\to$ `foo` inode $\\to$ `foo` 数据块 $\\to$ `bar` inode（共 $5$ 次读）。\n- 写前读位图：读数据位图寻找空闲块（$1$ 次读）。\n- 写：写入新数据块 + 更新数据位图 + 更新 `bar` inode（大小与指针）（共 $3$ 次写）。\n总计 $6$ 次读 I/O 与 $3$ 次写 I/O。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch42-03", "title": "Ordered Journaling 中元数据与数据写入顺序约束", "diff": "中档", "hint": "1. **破题思路**：分析为何 Ordered Mode 必须强制要求数据块先于日志事务落盘。\n2. **解答要点**：在 Ordered Journaling（如 ext3/ext4 默认模式）中，日志仅记录 inode 与位图等元数据变更，不记录用户数据块本身。若先提交元数据日志再写数据块，当系统在二者之间崩溃时，重启重放日志后 `inode` 会合法地指向一个尚未写入新数据的旧磁盘块，从而暴露上一任用户的敏感残留数据（严重安全与一致性漏洞）。因此必须遵循：**写数据块并 Flush $\\to$ 写日志头部与元数据 $\\to$ Flush $\\to$ 写 TxE 提交块并 Flush $\\to$ Checkpoint**。"}, {"oj": "教材精选题", "pid": "OSTEP-Ch43-04", "title": "日志结构文件系统 (LFS) 写放大与垃圾回收成本分析", "diff": "压轴", "hint": "1. **破题思路**：利用段利用率 $u$ 推导清理（Cleaning）有效数据所需的读写带宽比例。\n2. **解答要点**：LFS 将随机写转化为顺序追加写，通过 `imap` 定位最新 inode。当磁盘接近写满时需回收旧段（Segment）。设旧段中存活数据比例（利用率）为 $u \\in (0, 1)$，清理 $1$ 个段需读取该段全部数据（$1$ 份读），将其中 $u$ 比例的存活块写往新段（$u$ 份写），释放出 $(1-u)$ 比例的空闲空间。因此每清理出 $1$ 单位空闲空间，总 I/O 开销为 $\\frac{1+u}{1-u}$。当 $u=0.8$ 时，写放大高达 $\\frac{1.8}{0.2} = 9$ 倍，这解释了为何 LFS/SSD FTL 需要区分冷热数据并保持预留空间（Over-provisioning）。"}]}]}, {"id": "yan_ds", "name": "严蔚敏 · 数据结构（C语言版）", "author": "严蔚敏、吴伟民", "level": "数据结构与算法基石", "chapters": [{"cid": "YAN-01", "title": "线性表、单链表与栈/队列应用", "summary": "线性结构的核心在于元素间严格的一对一前驱后继关系。顺序表依托连续内存实现 $O(1)$ 随机访问，但中间插入删除需移动 $O(n)$ 个元素；单链表通过指针域串联离散节点，实现已知前驱后的 $O(1)$ 节点摘除与拼接，引入头节点（Dummy Head）可将首元节点操作与普通节点统一，大幅消除边界特判。栈（LIFO）与队列（FIFO）作为操作受限的线性表，分别是递归消除、表达式求值与广度优先搜索（BFS）、缓冲区调度的基础。循环队列通过模运算 `(rear + 1) % MAXQSIZE == front` 解决“假溢出”问题，并借助预留一个空位或额外计数器区分队空与队满状态。", "template_cpp": "#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct LNode {\n    int data;\n    struct LNode *next;\n} LNode, *LinkList;\n\nLinkList reverse_list(LinkList head) {\n    LNode *prev = NULL, *curr = head->next;\n    while (curr) {\n        LNode *nxt = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = nxt;\n    }\n    head->next = prev;\n    return head;\n}\n\nint main() {\n    LNode dummy = {0, NULL};\n    for (int i = 3; i >= 1; --i) {\n        LNode *p = (LNode*)malloc(sizeof(LNode));\n        p->data = i; p->next = dummy.next; dummy.next = p;\n    }\n    reverse_list(&dummy);\n    for (LNode *p = dummy.next; p; p = p->next) printf(\"%d \", p->data);\n    return 0;\n}", "pitfalls": "单链表原地逆置或删除节点时未提前保存 `next` 指针导致断链内存泄漏；循环队列判满条件写错导致少存元素或与判空混淆；中缀转后缀表达式时未正确处理同级运算符左结合性或括号匹配。", "workbench_tags": ["线性表", "单链表", "栈", "循环队列"], "problems": [{"oj": "教材精选题", "pid": "Yan-Ch02-01", "title": "有序单链表原地归并（去重与保留分析）", "diff": "基础", "hint": "1. **破题思路**：利用双指针 `pa, pb` 同步扫描两递增链表，直接复用原节点指针串联，空间复杂度 $O(1)$。\n2. **解答要点**：设头节点 `Lc = La`，`pc = Lc`，`pa = La->next`，`pb = Lb->next`。循环比较 `pa->data` 与 `pb->data`，将较小者接在 `pc->next` 后并后移对应指针；若要求递增去重，当二者相等时接入 `pa` 并释放 `pb` 节点。循环结束后将非空剩余段直接挂接至 `pc->next`，释放 `Lb` 头节点，时间复杂度 $O(m+n)$。"}, {"oj": "教材精选题", "pid": "Yan-Ch03-02", "title": "双栈实现算术表达式求值（中缀直接求值）", "diff": "中档", "hint": "1. **破题思路**：维护运算符栈 `OPTR` 与操作数栈 `OPND`，依据算符优先关系表决定压栈或退栈计算。\n2. **解答要点**：预先压入哨兵 `'#'`。扫描表达式：遇数字直接压入 `OPND`；遇运算符 $\\theta$ 与 `OPTR` 栈顶算符 $\\theta_1$ 比较优先级：(1) $\\theta_1 < \\theta$，压入 $\\theta$；(2) $\\theta_1 == \\theta$（如 `'('` 与 `')'`），弹出 `'('` 抵消；(3) $\\theta_1 > \\theta$，弹出 $\\theta_1$ 及 `OPND` 顶两个操作数 $b, a$（注意出栈顺序：先出为右操作数 $b$，后出为左操作数 $a$），计算 $a \\,\\theta_1\\, b$ 压回 `OPND`，继续比较当前 $\\theta$。"}, {"oj": "教材精选题", "pid": "Yan-Ch03-03", "title": "仅用 tag 标志域的无浪费循环队列入队与出队", "diff": "中档", "hint": "1. **破题思路**：不浪费数组空间，通过附加状态位 `tag` 记录最后一次操作是入队还是出队。\n2. **解答要点**：队列满与空均满足 `front == rear`。设 `tag = 0` 表示上次操作为出队，`tag = 1` 表示上次为入队。初始 `front = rear = 0, tag = 0`。入队条件：不可满足 `front == rear && tag == 1`；入队后置 `tag = 1`。出队条件：不可满足 `front == rear && tag == 0`；出队后置 `tag = 0`。空间利用率达 $100\\%$。"}, {"oj": "教材精选题", "pid": "Yan-Ch02-04", "title": "单链表倒数第 k 个节点与环入口 O(1) 空间定位", "diff": "压轴", "hint": "1. **破题思路**：利用快慢指针的固定步距差或速度差建立几何等式。\n2. **解答要点**：(1) 倒数第 $k$ 个：快指针先走 $k$ 步，随后快慢同步每次 $1$ 步，快指针到 `NULL` 时慢指针恰在倒数第 $k$ 个；(2) 环入口：快指针每次 $2$ 步、慢指针每次 $1$ 步，相遇时设头到入口距 $a$，入口到相遇点距 $b$，环余长 $c$，则 $2(a+b) = a+b+n(b+c) \\implies a = (n-1)(b+c)+c$。此时令一指针回表头与慢指针同步每次 $1$ 步，必在环入口精准相遇。"}]}, {"cid": "YAN-02", "title": "串、KMP 模式匹配与稀疏矩阵压缩", "summary": "字符串模式匹配的核心在于消除主串指针的回溯。朴素（BF）算法在失配时主串指针 $i$ 回退至 $i-j+2$，最坏时间复杂度达 $O(nm)$。Knuth-Morris-Pratt（KMP）算法通过预处理模式串构建 `next` 数组（即每个前缀的最长相等真前后缀长度），在 $T[i] \\neq P[j]$ 时保持 $i$ 不动，仅将模式串右移至 $j = \\text{next}[j]$，将整体匹配复杂度降至严格的 $O(n+m)$。进一步地，当 $P[j] == P[\\text{next}[j]]$ 时可直接跳过无效比较，优化为 `nextval` 数组。对于高阶稀疏矩阵，教材采用三元组顺序表或十字链表存储非零元，结合列频统计实现 $O(n+t)$ 的快速转置。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvector<int> build_next(const string& p) {\n    int m = p.size();\n    vector<int> nxt(m, 0);\n    for (int i = 1, j = 0; i < m; ++i) {\n        while (j > 0 && p[i] != p[j]) j = nxt[j - 1];\n        if (p[i] == p[j]) ++j;\n        nxt[i] = j;\n    }\n    return nxt;\n}\n\nint kmp_search(const string& t, const string& p) {\n    if (p.empty()) return 0;\n    auto nxt = build_next(p);\n    for (int i = 0, j = 0; i < (int)t.size(); ++i) {\n        while (j > 0 && t[i] != p[j]) j = nxt[j - 1];\n        if (t[i] == p[j]) ++j;\n        if (j == (int)p.size()) return i - j + 1;\n    }\n    return -1;\n}", "pitfalls": "严蔚敏教材采用 $1$-indexed 下标（`next[1]=0`）而 C++/算法题普遍采用 $0$-indexed（前缀函数 `pi[0]=0`），混用两套下标公式会导致偏移差 $1$；计算 `nextval` 时未按顺序递推而是直接覆盖旧 `next` 值。", "workbench_tags": ["KMP", "模式匹配", "nextval", "稀疏矩阵"], "problems": [{"oj": "教材精选题", "pid": "Yan-Ch04-01", "title": "模式串 `abaabcac` 的 next 与 nextval 数组手工求解", "diff": "基础", "hint": "1. **破题思路**：按严蔚敏 $1$-indexed 定义（`next[1]=0`，`next[j]` 为前 $j-1$ 字符最长相等真前后缀长度 $+1$）逐位推导。\n2. **解答要点**：模式串 $P = \\text{a b a a b c a c}$（下标 $1\\sim 8$）。\n- `next`: $[0, 1, 1, 2, 2, 3, 1, 2]$。\n- `nextval`: 若 $P[j] == P[\\text{next}[j]]$ 则继承 `nextval[next[j]]`，否则保留 `next[j]`。\n逐位计算得 `nextval`: $[0, 1, 0, 2, 1, 3, 0, 2]$。当第 $7$ 位 `'a'` 失配时直接跳回 $0$（主串后移），省去无意义的 $1$ 号位 `'a'` 比较。"}, {"oj": "教材精选题", "pid": "Yan-Ch05-02", "title": "三元组稀疏矩阵 O(n+t) 快速转置算法", "diff": "中档", "hint": "1. **破题思路**：预先统计原矩阵每列非零元个数 `num[col]`，通过前缀和得出转置后各行起始位置 `cpot[col]`。\n2. **解答要点**：设原矩阵 $m \\times n$ 含 $t$ 个非零元。第一遍扫描 $t$ 个三元组统计 `num[col]`；第二遍计算 `cpot[1]=1, cpot[c] = cpot[c-1] + num[c-1]`（$c=2\\dots n$）；第三遍顺序扫描原三元组 $(r, c, v)$，直接将其写入转置表下标 `cpot[c]` 处并将 `cpot[c]++`。总时间复杂度 $O(n+t)$，较朴素按列扫描的 $O(n \\cdot t)$ 大幅提升。"}, {"oj": "教材精选题", "pid": "Yan-Ch04-03", "title": "KMP 自动机与周期串最小循环节判定", "diff": "中档", "hint": "1. **破题思路**：利用 $0$-indexed 前缀函数 $\\pi[n-1]$ 与字符串总长 $n$ 的整除性质。\n2. **解答要点**：设串长为 $n$，最长相等真前后缀长度为 $L = \\pi[n-1]$。若 $L > 0$ 且 $(n - L) \\mid n$，则该串必然由长度为 $d = n - L$ 的最小循环节重复 $\\frac{n}{d}$ 次构成。证明思路：由前后缀相等关系逐段向右平移 $d$ 步可归纳出对所有 $i \\ge d$ 均有 $S[i] = S[i-d]$。"}, {"oj": "教材精选题", "pid": "Yan-Ch05-04", "title": "对称矩阵与三对角矩阵一维压缩地址映射推导", "diff": "基础", "hint": "1. **破题思路**：等差数列求和计算下三角或带状区域在目标下标之前的元素总数。\n2. **解答要点**：(1) $n$ 阶下三角对称矩阵（行优先 $1$-indexed）：对于 $i \\ge j$，前 $i-1$ 行共 $\\frac{i(i-1)}{2}$ 个元素，第 $i$ 行在其前有 $j-1$ 个，故下标 $k = \\frac{i(i-1)}{2} + j - 1$（$0$-indexed）；若 $i < j$ 则交换 $i, j$。(2) 三对角矩阵（$|i-j| \\le 1$）：前 $i-1$ 行共 $3(i-1)-1$ 个元素，第 $i$ 行偏移 $j-i+1$，故 $k = 2i + j - 3$（$0$-indexed 为 $2(i-1)+j-1$）。"}]}, {"cid": "YAN-03", "title": "二叉树遍历、线索化与哈夫曼编码", "summary": "二叉树是递归结构与层次索引的核心载体。先序、中序与后序遍历本质上对应深度优先搜索（DFS）中访问根节点的三个时机，通过显式栈可消除递归开销；而层次遍历借助队列实现广度优先访问。对于含 $n$ 个节点的二叉链表，存在 $n+1$ 个空指针域，线索二叉树（Threaded Binary Tree）利用 `ltag/rtag` 标志位将这些空指针改造为指向前驱与后继的线索，从而在 $O(1)$ 额外空间下实现中序遍历。哈夫曼树（最优二叉树）通过贪心策略每次合并权值最小的两棵子树，使带权路径长度 $\\text{WPL} = \\sum w_i l_i$ 达到理论极小值，其左右分支赋予 `0/1` 即可生成无二义性的最优前缀编码。", "template_cpp": "#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint huffman_wpl(vector<int>& weights) {\n    priority_queue<int, vector<int>, greater<int>> pq(weights.begin(), weights.end());\n    int wpl = 0;\n    while (pq.size() > 1) {\n        int a = pq.top(); pq.pop();\n        int b = pq.top(); pq.pop();\n        wpl += (a + b);\n        pq.push(a + b);\n    }\n    return wpl;\n}\n\nint main() {\n    vector<int> w = {5, 29, 7, 8, 14, 23, 3, 11};\n    cout << \"Min WPL = \" << huffman_wpl(w) << \"\\n\";\n    return 0;\n}", "pitfalls": "仅凭先序+后序序列无法唯一确定二叉树（除非每个非叶节点度均为 $2$）；线索二叉树中寻找后序后继需区分右子树存在与否及双亲指针；非递归后序遍历忘记记录 `last_visited` 指针导致右子树死循环。", "workbench_tags": ["二叉树", "非递归遍历", "线索二叉树", "哈夫曼树"], "problems": [{"oj": "教材精选题", "pid": "Yan-Ch06-01", "title": "先序+中序唯一重构二叉树及后序输出", "diff": "基础", "hint": "1. **破题思路**：先序首元素定根，在中序中定位根以切分左右子树区间大小，递归构造。\n2. **解答要点**：设先序 `ABDGCEF`，中序 `DGBAECF`。首字符 `'A'` 为根，中序中 `'A'` 左侧 `DGB`（长 $3$）为左子树，右侧 `ECF`（长 $3$）为右子树。切分先序为左 `BDG`、右 `CEF`，递归得左子根 `'B'`（左 `DG`）、右子根 `'C'`（左 `'E'` 右 `'F'`）。最终后序序列为 `GDBEFCA`。利用哈希表预处理中序下标可将总时间降至 $O(n)$。"}, {"oj": "教材精选题", "pid": "Yan-Ch06-02", "title": "树、森林与二叉树的相互转换（长子-兄弟表示法）", "diff": "中档", "hint": "1. **破题思路**：左指针指向第一个孩子（长子），右指针指向下一个兄弟。\n2. **解答要点**：森林中各棵树的根节点视为互为兄弟，用右指针串联。**重要等价定理**：森林的先序遍历 $\\iff$ 对应二叉树的先序遍历；森林的中序（后根）遍历 $\\iff$ 对应二叉树的中序遍历。例如一棵树有 $n$ 个节点且有 $k$ 个叶子，转换为二叉树后，无左孩子的节点数（代表原树无孩子节点，即叶子）恰好等于 $k$。"}, {"oj": "教材精选题", "pid": "Yan-Ch06-03", "title": "中序线索二叉树中求任意节点 p 的中序后继", "diff": "中档", "hint": "1. **破题思路**：依据 `rtag` 判断 `rchild` 是真实右子树还是中序后继线索。\n2. **解答要点**：若 `p->rtag == 1`，则 `p->rchild` 直接就是中序后继；若 `p->rtag == 0`，说明 `p` 存在右子树，其中序后继必为右子树中**最左下角**的节点——即从 `q = p->rchild` 出发，只要 `q->ltag == 0` 就不断执行 `q = q->lchild`，最终 `q` 即为所求后继。整个过程无需栈与递归。"}, {"oj": "教材精选题", "pid": "Yan-Ch06-04", "title": "k 叉哈夫曼树虚节点补充与 WPL 证明", "diff": "压轴", "hint": "1. **破题思路**：保证每次合并 $k$ 个节点时，最后一次恰好剩余 $k$ 个节点（即总节点数满足 $(n-1) \\equiv 0 \\pmod{k-1}$）。\n2. **解答要点**：每次合并减少 $k-1$ 个节点。若原有 $n$ 个权值，当 $(n-1) \\bmod (k-1) \\neq 0$ 时，必须先补充 $m = (k-1) - ((n-1) \\bmod (k-1))$ 个权值为 $0$ 的虚叶节点，再每次取最小 $k$ 个合并。若不补 $0$ 节点而最后一次少取，会导致靠近根部的短编码位未用满，整体 $\\text{WPL}$ 偏大。"}]}, {"cid": "YAN-04", "title": "图论：存储、MST、拓扑排序与最短路径", "summary": "图是表达任意多对多关系的抽象结构。邻接矩阵适合稠密图与 $O(1)$ 边存在性查询，邻接表（或链式前向星）以 $O(V+E)$ 空间支撑稀疏图高效遍历。最小生成树（MST）基于切分定理：Prim 算法类似 Dijkstra，从单点逐步扩张连通分量，适合稠密图；Kruskal 算法按边权升序结合并查集（Union-Find）判环，时间复杂度 $O(E \\log E)$，适合稀疏图。有向无环图（DAG）支持拓扑排序与关键路径（AOE 网最早/最迟发生时间）计算。单源最短路径 Dijkstra 利用贪心松弛要求边权非负，而 Floyd-Warshall 通过三重动态规划以 $O(V^3)$ 求解全源最短路并允许存在负权边。", "template_cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nvector<long long> dijkstra(int n, int s, const vector<vector<pair<int,int>>>& adj) {\n    const long long INF = 1e18;\n    vector<long long> dist(n + 1, INF);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;\n    dist[s] = 0; pq.push({0, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d > dist[u]) continue;\n        for (auto [v, w] : adj[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n    return dist;\n}", "pitfalls": "Dijkstra 误用于含负权边的图导致局部最优不可修正；Floyd 三重循环中转点 `k` 未放在最外层导致状态转移错误；优先队列版本 Dijkstra 弹出节点时忘记 `if (d > dist[u]) continue;` 造成冗余松弛超时。", "workbench_tags": ["图论", "最小生成树", "Dijkstra", "关键路径"], "problems": [{"oj": "教材精选题", "pid": "Yan-Ch07-01", "title": "Kruskal 与 Prim 算法求解连通网最小生成树", "diff": "基础", "hint": "1. **破题思路**：按边权升序加边并查集判环（Kruskal），或维护点集到未选点集的最小边权（Prim）。\n2. **解答要点**：Kruskal 每次选全局最小边 $(u, v)$，若 `find(u) != find(v)` 则合并并累加权值，直至选满 $V-1$ 条边。当图中存在权值相同的多条边时，MST 形态可能不唯一，但**最小总权值必然唯一**。若所有边权互异，则 MST 形态也唯一。"}, {"oj": "教材精选题", "pid": "Yan-Ch07-02", "title": "AOE 网事件最早/最迟发生时间与关键路径求解", "diff": "中档", "hint": "1. **破题思路**：正序拓扑求 $ve[k]$，逆序拓扑求 $vl[k]$，对比活动 $e(i)=ve[u]$ 与 $l(i)=vl[v]-w$。\n2. **解答要点**：(1) 正向按拓扑序：$ve[v] = \\max_{(u,v) \\in E} \\{ve[u] + w(u,v)\\}$，起点 $ve[0]=0$；(2) 反向按逆拓扑序：$vl[u] = \\min_{(u,v) \\in E} \\{vl[v] - w(u,v)\\}$，终点 $vl[n-1]=ve[n-1]$；(3) 满足 $ve[u] == vl[v] - w(u,v)$ 的边即为关键活动。缩短工期必须同时压缩所有并行关键路径上的共同或独立关键活动。"}, {"oj": "教材精选题", "pid": "Yan-Ch07-03", "title": "Dijkstra 算法手算松弛表与负权反例构造", "diff": "中档", "hint": "1. **破题思路**：构造包含正权直达边与负权绕路边的最小反例，说明贪心确定集合 $S$ 的不可逆性。\n2. **解答要点**：设源点 $S$ 到 $A$ 边权 $2$，$S$ 到 $B$ 边权 $5$，$B$ 到 $A$ 边权 $-4$。Dijkstra 第一步选出 $dist[A]=2$ 并将 $A$ 锁死入集合 $S$；第二步访问 $B(5)$ 时通过 $B \\to A$ 发现 $5 + (-4) = 1 < 2$，但 $A$ 已被标记出队或无法二次更新其后续邻居的最短路，从而得出错误结果。"}, {"oj": "教材精选题", "pid": "Yan-Ch07-04", "title": "利用 BFS 或拓扑排序判定有向图强连通与环路", "diff": "压轴", "hint": "1. **破题思路**：Kahn 算法统计入度为 $0$ 节点出队总数；DFS 利用三色标记（白/灰/黑）或 Tarjan 强连通分量。\n2. **解答要点**：在 Kahn 拓扑排序中，若最终出队顶点数 $< |V|$，则剩余节点必包含至少一个有向环（因为环上节点入度永不为 $0$）。若需定位所有强连通分量，Tarjan 算法维护 `dfn[u]`（发现时间戳）与 `low[u]`（能追溯到的最早栈内祖先），当 `dfn[u] == low[u]` 时弹栈直至 `u`，即得一个极大强连通分量，整体复杂度 $O(V+E)$。"}]}, {"cid": "YAN-05", "title": "查找（AVL/B+树/哈希）与内部排序", "summary": "静态查找中折半查找利用有序性将比较次数压至 $\\lfloor \\log_2 n \\rfloor + 1$。动态查找需维护树高平衡：AVL 树通过四种旋转（LL/RR/LR/RL）严格维持左右子树高度差 $|BF| \\le 1$；面向磁盘外存的 B 树与 B+ 树大幅提升分支因子 $m$ 以压低树高，其中 B+ 树将全部记录索引下沉至叶节点并用链表串联，完美适配区间扫描与数据库索引。内部排序中，快速排序依托枢轴划分实现平均 $O(n \\log n)$ 原地排序，但最坏退化为 $O(n^2)$；归并排序稳定且最坏仍为 $O(n \\log n)$；堆排序仅需 $O(1)$ 辅助空间。基于比较的排序算法下界严格为 $\\Omega(n \\log n)$，突破该下界需依赖基数排序等非比较策略。", "template_cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid quick_sort(vector<int>& a, int l, int r) {\n    if (l >= r) return;\n    int pivot = a[l + (r - l) / 2], i = l - 1, j = r + 1;\n    while (i < j) {\n        do ++i; while (a[i] < pivot);\n        do --j; while (a[j] > pivot);\n        if (i < j) swap(a[i], a[j]);\n    }\n    quick_sort(a, l, j);\n    quick_sort(a, j + 1, r);\n}\n\nint main() {\n    vector<int> a = {49, 38, 65, 97, 76, 13, 27, 49};\n    quick_sort(a, 0, (int)a.size() - 1);\n    for (int x : a) cout << x << ' ';\n    return 0;\n}", "pitfalls": "AVL 插入/删除后旋转方向判断错误（LR 型需先对左孩子左旋再对根右旋）；快排枢轴取首元素在有序数组上退化为 $O(n^2)$ 且爆栈；误以为堆排序与希尔排序是稳定排序。", "workbench_tags": ["AVL树", "B+树", "快速排序", "堆排序"], "problems": [{"oj": "教材精选题", "pid": "Yan-Ch09-01", "title": "AVL 树插入序列最小不平衡子树四种旋转演示", "diff": "基础", "hint": "1. **破题思路**：自底向上回溯首个 $|BF|=2$ 的节点，根据插入路径前两步方向确定 LL/RR/LR/RL 类型。\n2. **解答要点**：依次插入 `{16, 3, 7, 11, 9, 26, 18, 14, 15}`。\n- 插入 `7` 时，根 `16` 的 $BF=2$，路径为先左（`3`）后右（`7`），属 **LR 型**：先以 `3` 为轴左旋使 `7` 上位，再以 `16` 为轴右旋，根变为 `7`。\n- 后续插入 `9` 触发对 `3` 的 **RL 型**双旋。掌握“单旋看同侧，双旋先转下层再转上层”即可零失误。"}, {"oj": "教材精选题", "pid": "Yan-Ch09-02", "title": "m 阶 B 树关键字个数范围与插入分裂规则", "diff": "中档", "hint": "1. **破题思路**：牢记 $m$ 阶 B 树非根非叶节点关键字数范围 $[\\lceil m/2 \\rceil - 1, m - 1]$。\n2. **解答要点**：设 $m=5$，则非根节点至少含 $\\lceil 5/2 \\rceil - 1 = 2$ 个关键字，至多含 $4$ 个关键字。插入第 $5$ 个关键字导致溢出时，取第 $\\lceil m/2 \\rceil = 3$ 个关键字**上移**至父节点，左右各 $2$ 个关键字分裂为两个独立子节点。若父节点也溢出则级联上裂直至根节点（此时树高 $+1$）。"}, {"oj": "教材精选题", "pid": "Yan-Ch09-03", "title": "开放定址线性探测法 ASL 成功与不成功计算", "diff": "中档", "hint": "1. **破题思路**：严格区分**查找成功**（对已有元素求平均）与**查找失败**（对所有散列地址 $0 \\sim p-1$ 到首个空位距离求平均）。\n2. **解答要点**：设散列表长 $11$（下标 $0\\sim 10$），$H(k) = k \\bmod 11$，线性探测解决冲突。填入 $6$ 个元素后表内各槽位占用情况确定。$\text{ASL}_{\\text{succ}}$ 仅对这 $6$ 个已填入元素求平均探测次数；而 $\\text{ASL}_{\\text{unsucc}}$ 必须对 $H(k) \\in \\{0, 1, \\dots, 10\\}$ 共 $11$ 个初始散列位置分别数出“向后探测直到遇到空槽（含空槽本身）”的次数并除以 $11$（注意分母是 $p=11$ 而非表长或元素数）。"}, {"oj": "教材精选题", "pid": "Yan-Ch10-04", "title": "基于比较的排序算法下界 Ω(n log n) 决策树证明", "diff": "压轴", "hint": "1. **破题思路**：将任意确定性比较排序映射为二叉树，利用叶节点数量下界反推树高。\n2. **解答要点**：$n$ 个互异元素共有 $n!$ 种全排列，任何正确的比较排序决策树必须至少拥有 $n!$ 个叶节点才能区分每种输入排列。设决策树高为 $h$，二叉树叶节点数至多为 $2^h$，故 $2^h \\ge n!$。两边取对数并应用斯特林公式 $\\ln(n!) = n\\ln n - n + O(\\ln n)$，可得 $h \\ge \\log_2(n!) = \\Omega(n \\log n)$，即最坏情况比较次数不可能低于该下界。"}]}]}, {"id": "gh_bupt_ds_os", "name": "🎓 北邮 CS 学长攻略（数据结构 / CSAPP / OS）", "author": "faranten & Holour & Yokumii · GitHub", "level": "手写代码 + 英文考试 + 实验避坑", "repo_url": "https://github.com/Holour/BUPT-Learning_Materials", "chapters": [{"cid": "BUPT-DSOS-01", "title": "北邮数据结构、计算机系统基础与操作系统实战指南", "summary": "1) 数据结构：北邮课程节奏稳，但期末需要【手写完整 C/C++ 代码】，务必反复吃透课程 PPT 并结合严蔚敏教材（参考 Holour/BUPT-Learning_Materials 笔记）；数据结构课设建议提前选好队友并做前后端分离/多线程/图形化。2) 计算机系统基础：即 CMU CSAPP 体系，4 次实验（DataLab/BombLab/AttackLab/CacheLab）是精髓。3) 操作系统：为【英文考试】，黑砖教材需从头到尾通读串起虚拟化-并发-持久化全局脉络，单靠背零散知识点难以拿高分。", "template_cpp": "手写代码高频必考：单链表逆置/合并、二叉树非递归遍历/层序、AVL 旋转、Dijkstra/Kruskal/拓扑排序、快排/堆排序、PV 信号量同步。", "pitfalls": "机试过得了但考场纸面手写代码漏边界判空；OS 英文卷混淆 Page Fault / Thrashing / Semaphore 英文表述。", "workbench_tags": ["北邮考情", "手写代码", "英文考试"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "数据结构与操作系统 · 考前1页纸速查卡", "sections": [{"heading": "一、内存架构、对齐与 CPU Cache", "items": [{"name": "结构体内存对齐与填充", "formula": "$\\text{offset}(m_i) \\equiv 0 \\pmod{\\min(a_i, P)},\\quad \\text{sizeof}(S) \\equiv 0 \\pmod{\\max_i a_i}$", "note": "按成员大小降序排列可减少内部填充；C++ alignas(64) 可强制按 Cache Line 对齐。"}, {"name": "Cache 地址拆分与 AMAT", "formula": "$\\text{AMAT} = T_{\\text{hit}} + \\text{MR} \\times \\text{MP},\\quad \\text{Offset}=\\log_2 B,\\ \\text{Index}=\\log_2 S$", "note": "B 为块大小（通常 64B），S 为组数；顺序访问命中率远高于跨步/随机跳跃访问。"}, {"name": "伪共享 (False Sharing)", "formula": "$\\text{Padding} = 64\\text{B} - \\text{sizeof}(T),\\quad \\text{MESI: } M \\leftrightarrow I \\text{ 乒乓}$", "note": "多核线程修改同一 64B 缓存行的不同变量会触发缓存行无效化，需用 alignas(64) 隔离。"}, {"name": "AoS vs SoA 数据布局", "formula": "$\\text{AoS: }\\text{struct }P[N]\\quad\\text{vs}\\quad\\text{SoA: }\\text{struct }\\{T\\ x[N], y[N]\\}$", "note": "只遍历少数几个字段时，SoA 显著提高缓存行有效载荷利用率并支持 SIMD 向量化。"}, {"name": "四级页表与 TLB 有效访问时间", "formula": "$\\text{VA}_{48} = 9+9+9+9+12,\\quad \\text{EAT} = h(t_{\\text{TLB}}+t_m)+(1-h)(t_{\\text{TLB}}+5t_m)$", "note": "4KB 页对应 12 位页内偏移；大页 (2MB/1GB) 可减少页表级数并降低 TLB Miss 率。"}]}, {"heading": "二、进程、线程与调度器", "items": [{"name": "I/O 密集型最佳线程池大小", "formula": "$N_{\\text{threads}} = N_{\\text{CPU}} \\times U_{\\text{CPU}} \\times \\left(1 + \\frac{T_{\\text{wait}}}{T_{\\text{compute}}}\\right)$", "note": "CPU 密集型取 $N_{\\text{CPU}}$ 或 $N_{\\text{CPU}}+1$；过多线程会加剧上下文切换与缓存颠簸。"}, {"name": "Linux CFS 权重与虚拟运行时间", "formula": "$\\Delta vruntime = \\Delta t_{\\text{exec}} \\times \\frac{W_0}{W_i},\\quad \\text{CPU占比}_i = \\frac{W_i}{\\sum_j W_j}$", "note": "nice 值每降 1，权重约增 1.25 倍（CPU 时间约增 25%）；红黑树按 vruntime 最小者调度。"}, {"name": "僵尸进程 vs 孤儿进程", "formula": "$\\text{Zombie: } \\text{exit()} \\land \\neg\\text{wait()},\\quad \\text{Orphan: } \\text{PPID}_{\\text{dead}} \\to 1$", "note": "僵尸进程占用 PID 与 PCB 槽位，需父进程 waitpid() 或 SIGCHLD 回收；孤儿进程由 init/systemd 领养。"}, {"name": "fork() 写时复制与缓冲区陷阱", "formula": "$\\text{fork()} \\implies \\text{COW 页表只读},\\quad \\text{stdio 缓冲未 }\\text{fflush()} \\implies \\text{打印 } 2^k \\text{ 次}$", "note": "重定向到文件时 stdout 为全缓冲，fork 前未刷新会导致父子进程各输出一份缓冲内容。"}, {"name": "页置换与工作集模型", "formula": "$\\text{Belady 异常: FIFO},\\quad \\text{栈式算法 (LRU/OPT): } M(m,r) \\subseteq M(m+1,r)$", "note": "LRU/OPT 满足包含性，不会出现 Belady 异常；Linux 近似用双链表 Clock/Active-Inactive LRU。"}]}, {"heading": "三、并发同步与无锁编程", "items": [{"name": "死锁四必要条件与破坏", "formula": "$\\text{互斥} \\land \\text{占有且等待} \\land \\text{不可抢占} \\land \\text{循环等待}$", "note": "破环循环等待最常用：全局统一加锁顺序（如按地址序）或使用 C++ std::scoped_lock。"}, {"name": "条件变量虚假唤醒与 while 范式", "formula": "$\\text{while }(!\\text{pred}())\\ \\{\\ \\text{cv.wait(lk)};\\ \\}$", "note": "禁止用 if 代替 while；OS 信号或广播唤醒后条件可能已被其他线程改回不满足。"}, {"name": "自旋锁 vs 互斥锁选型边界", "formula": "$T_{\\text{hold}} < 2 \\times T_{\\text{ctx\\_switch}} \\implies \\text{Spinlock},\\quad \\text{否则 Mutex}$", "note": "单核不可用用户态纯自旋锁；持锁期间可能睡眠或发生缺页异常时严禁使用自旋锁。"}, {"name": "CAS 无锁栈与 ABA 问题", "formula": "$\\text{CAS}(addr, expected, desired),\\quad \\text{ABA: } A \\to B \\to A \\implies \\text{Tagged Pointer}$", "note": "仅比对指针值会误判节点未变，需配合 64 位版本计数/危险指针 (Hazard Pointer) 或 Epoch 回收。"}, {"name": "读写锁写饥饿与内存序", "formula": "$\\text{Release-Acquire: } \\text{store}(release) \\xrightarrow{\\text{synchronizes-with}} \\text{load}(acquire)$", "note": "读优先读写锁会导致写线程无限饥饿；无锁 SPSC 队列用 acquire/release 即可保证可见性。"}]}, {"heading": "四、系统调用、I/O 多路复用与零拷贝", "items": [{"name": "传统 read+write vs sendfile 拷贝次数", "formula": "$\\text{read+write: } 4\\text{ 次拷贝}+4\\text{ 次切换},\\quad \\text{sendfile+SG: } 2\\text{ 次DMA}+2\\text{ 次切换}$", "note": "支持 Scatter-Gather DMA 时，sendfile 直接将 Page Cache 描述符交给网卡，实现零 CPU 拷贝。"}, {"name": "select / poll vs epoll 复杂度", "formula": "$\\text{select/poll: } O(N) \\text{ 每次轮询},\\quad \\text{epoll: } O(1) \\text{ 就绪链表} + O(\\log N) \\text{ 红黑树}$", "note": "epoll_wait 仅返回活跃 fd；连接数大且活跃比例低时 epoll 性能远超 select/poll。"}, {"name": "epoll LT (水平触发) vs ET (边缘触发)", "formula": "$\\text{LT: 缓冲非空即反复通知},\\quad \\text{ET: 仅状态跳变通知一次}$", "note": "ET 模式必须搭配非阻塞 fd，并循环 read/write 直到返回 EAGAIN/EWOULDBLOCK。"}, {"name": "vDSO 加速原理", "formula": "$\\text{gettimeofday() / clock\\_gettime()} \\xrightarrow{\\text{vDSO}} \\text{用户态直接读共享时钟页}$", "note": "内核将只读时间页映射进用户地址空间，消除陷入内核态的上下文切换与 Spectre 缓解开销。"}, {"name": "Page Cache 与落盘语义", "formula": "$\\text{write()} \\to \\text{Page Cache (Dirty)},\\quad \\text{fsync()} \\ge \\text{fdatasync()}$", "note": "fsync 同步数据与全部元数据（如 mtime），fdatasync 仅同步数据及必要大小元数据，延迟更低。"}]}, {"heading": "五、核心数据结构与存储引擎", "items": [{"name": "红黑树性质与黑高上界", "formula": "$h \\le 2\\log_2(n+1),\\quad \\text{根黑、叶NIL黑、红不相邻、任一节点到叶黑高相等}$", "note": "插入最多 2 次旋转、删除最多 3 次旋转，适合内存频繁修改的有序索引（如 Linux VMA/CFS）。"}, {"name": "B+ 树阶数与最大容量计算", "formula": "$N_{\\max}(h=3) = M^2 \\times L_{\\max},\\quad \\text{节点页内键数 } k \\approx \\lfloor \\frac{\\text{PageSize}}{\\text{Key}+\\text{Ptr}} \\rfloor$", "note": "B+ 树非叶节点不存记录指针故扇出更大、树更矮，且叶子节点双向链表天然支持高效范围扫描。"}, {"name": "LSM-Tree 写放大与 Tombstone", "formula": "$\\text{写入: WAL} \\to \\text{MemTable} \\to \\text{SSTable (顺序写)},\\quad \\text{删除}=\\text{写 Tombstone}$", "note": "将随机写转为顺序追加写，吞吐极高；读可能需跨多层 SSTable，需用布隆过滤器剪枝。"}, {"name": "布隆过滤器误判率与最优哈希数", "formula": "$k_{\\text{opt}} = \\frac{m}{n}\\ln 2 \\approx 0.693\\frac{m}{n},\\quad p \\approx \\left(1 - e^{-kn/m}\\right)^k$", "note": "绝无假阴性（判不存在则一定不存在），存在假阳性；标准布隆过滤器不支持直接删除。"}, {"name": "主定理 (Master Theorem) 递推求解", "formula": "$T(n)=aT(n/b)+f(n),\\quad n^{\\log_b a}\\text{ 与 }f(n)\\text{ 比较}$", "note": "若 $f(n)=\\Theta(n^{\\log_b a}\\log^k n)$，则 $T(n)=\\Theta(n^{\\log_b a}\\log^{k+1}n)$；否则取较大项。"}]}, {"heading": "六、系统网络栈与低延迟机制", "items": [{"name": "带宽时延积 (BDP) 与窗口设置", "formula": "$\\text{BDP} = \\text{Bandwidth} \\times \\text{RTT},\\quad W_{\\text{eff}} = \\min(\\text{rwnd}, \\text{cwnd})$", "note": "若 TCP 接收缓冲小于 BDP，高带宽长延迟链路永远无法跑满（需开启 Window Scaling 选项）。"}, {"name": "Nagle 算法 + Delayed ACK 40ms 死锁", "formula": "$\\text{小包写-写-读} \\land \\text{Nagle} \\land \\text{Delayed ACK} \\implies \\approx 40\\text{ms}\\text{ 延迟}$", "note": "低延迟 RPC/交易系统必须设置 TCP_NODELAY 禁用 Nagle，或合并 writev 一次性发出请求。"}, {"name": "TIME_WAIT 与 2MSL", "formula": "$\\text{主动关闭方进入 TIME\\_WAIT},\\quad \\text{持续 } 2\\text{MSL}\\ (\\text{Linux } 60\\text{s})$", "note": "防止旧连接迷途报文污染新五元组并确保最后 ACK 可靠到达；客户端海量短连接易耗尽本地端口。"}, {"name": "多线程环境下 fork() 死锁", "formula": "$\\text{fork() 仅复制调用线程},\\quad \\text{其他线程持有的锁永远处于 Locked}$", "note": "多线程程序中 fork 后子进程仅可安全调用 async-signal-safe 函数并立即 execve()。"}, {"name": "环形缓冲区与无锁 SPSC 索引", "formula": "$\\text{next} = (\\text{idx} + 1)\\ \\&\\ (N - 1)\\quad (N = 2^k)$", "note": "容量取 2 的幂用位与替代取模；head/tail 分置不同 64B 缓存行消除生产者-消费者伪共享。"}]}, {"heading": "七、高频易错点与考场避坑清单", "items": [{"name": "KMP next 数组下标与整体右移", "formula": "$\\text{next}[0]=-1\\text{ (或 }0\\text{)},\\quad \\text{前缀函数 } \\pi[i] = \\max\\{k < i+1 : s[0..k-1] = s[i-k+1..i]\\}$", "note": "考题常混用 0-based 与 1-based，务必先看清题目给定的 next[0] 或 next[1] 基准。"}, {"name": "并查集路径压缩 + 按秩合并复杂度", "formula": "$T(m, n) = O(m \\cdot \\alpha(n)),\\quad \\alpha(n) \\le 4 \\text{ (阿克曼反函数)}$", "note": "单用路径压缩或单用按秩合并均摊复杂度为 $O(\\log n)$，两者结合才达 $O(\\alpha(n))$。"}, {"name": "Dijkstra 负权边失效陷阱", "formula": "$\\text{Dijkstra 要求 } w(u,v) \\ge 0,\\quad \\text{含负权用 Bellman-Ford/SPFA } O(VE)$", "note": "已出队确定最短路的节点若遇负权边会破坏贪心最优子结构，导致答案错误。"}, {"name": "页号与页内偏移的进制换算", "formula": "$\\text{PageSize}=4\\text{KB}=2^{12}\\text{B} \\implies \\text{低 } 3 \\text{ 位十六进制为页内偏移}$", "note": "十六进制地址每 1 位占 4 bit，因此 12 位页内偏移恰好对应地址最右侧 3 个 hex 字符。"}, {"name": "信号量 P/V 操作顺序不可颠倒", "formula": "$\\text{先 } P(\\text{empty/full}) \\text{ 再 } P(\\text{mutex}),\\quad \\text{颠倒必死锁}$", "note": "先拿互斥锁再等资源同步信号量会导致生产者/消费者互锁，是 OS 大题第一高频丢分点。"}]}]};
